"""Symmetric polyomino shapes of size <= K, generated by ORBIT GROWTH.

Coordinates are doubled so that rotations about cell centres *and* about lattice
corners are exact integer maps:

    cell (r, c)  <->  (x, y) = (2c + 1, 2r + 1)

Every D4 element that maps cell centres to cell centres is then an affine map

    p -> M p + t

with ``M`` one of the seven non-identity matrices below and ``t`` an even
translation (even so that odd coordinates stay odd, i.e. cells map to cells).

A shape is *invariant* under such a ``g`` exactly when it is a union of
g-orbits, so we generate shapes by choosing whole orbits instead of choosing
cells.  Nothing is generated and then rejected for being asymmetric.

Completeness of the "each added orbit must touch the current set" rule: take a
spanning tree of the finished shape, walk it breadth-first from its smallest
cell, and add the orbit of each newly seen cell - that orbit contains the cell,
which is adjacent to its already-covered parent.  Requiring the seed orbit to
hold the shape's smallest cell makes each shape appear once per symmetry
element; duplicates across different elements are removed by canonical form.
"""

from __future__ import annotations

import time
from dataclasses import dataclass
from typing import Dict, FrozenSet, Iterator, List, Optional, Sequence, Set, Tuple

Cell = Tuple[int, int]

# The seven non-identity elements of D4, as 2x2 integer matrices.
D4: Dict[str, Tuple[Tuple[int, int], Tuple[int, int]]] = {
    "rot90":      ((0, -1), (1, 0)),
    "rot180":     ((-1, 0), (0, -1)),
    "rot270":     ((0, 1), (-1, 0)),
    "refl_vert":  ((-1, 0), (0, 1)),
    "refl_horiz": ((1, 0), (0, -1)),
    "refl_diag":  ((0, 1), (1, 0)),
    "refl_anti":  ((0, -1), (-1, 0)),
}

IDENTITY = ((1, 0), (0, 1))


def centre(cell: Cell) -> Tuple[int, int]:
    r, c = cell
    return (2 * c + 1, 2 * r + 1)


def cell_of(point: Tuple[int, int]) -> Cell:
    x, y = point
    return ((y - 1) // 2, (x - 1) // 2)


def apply(matrix, shift: Tuple[int, int], point: Tuple[int, int]) -> Tuple[int, int]:
    (m00, m01), (m10, m11) = matrix
    x, y = point
    return (m00 * x + m01 * y + shift[0], m10 * x + m11 * y + shift[1])


@dataclass(frozen=True)
class ShapeInfo:
    """Symmetry data for one cell set."""

    cells: FrozenSet[Cell]
    symmetric: bool
    capitol: Optional[Cell]
    # element name -> (shift, fixed cells)
    elements: Tuple[Tuple[str, Tuple[int, int], Tuple[Cell, ...]], ...]

    @property
    def size(self) -> int:
        return len(self.cells)


def analyse(cells: FrozenSet[Cell]) -> ShapeInfo:
    """Full symmetry analysis: group, fixed cells per element, capitol.

    A capitol exists iff every non-identity symmetry of the shape fixes exactly
    one cell, and it is the same cell for all of them.
    """
    pts = {c: centre(c) for c in cells}
    target = set(pts.values())
    min_x = min(p[0] for p in pts.values())
    min_y = min(p[1] for p in pts.values())

    found: List[Tuple[str, Tuple[int, int], Tuple[Cell, ...]]] = []
    for name, matrix in D4.items():
        moved = {c: apply(matrix, (0, 0), pts[c]) for c in cells}
        mx = min(p[0] for p in moved.values())
        my = min(p[1] for p in moved.values())
        shift = (min_x - mx, min_y - my)
        image = {c: (moved[c][0] + shift[0], moved[c][1] + shift[1]) for c in cells}
        if set(image.values()) == target:
            fixed = tuple(sorted(c for c in cells if image[c] == pts[c]))
            found.append((name, shift, fixed))

    capitol: Optional[Cell] = None
    if found:
        if all(len(f) == 1 for (_, _, f) in found):
            fixed_sets = {f[0] for (_, _, f) in found}
            if len(fixed_sets) == 1:
                capitol = next(iter(fixed_sets))
    return ShapeInfo(frozenset(cells), bool(found), capitol, tuple(found))


def canonical(cells: FrozenSet[Cell]) -> Tuple[Tuple[int, int], ...]:
    """Canonical form: min over the 8 D4 images, translated to the origin."""
    best: Optional[Tuple[Tuple[int, int], ...]] = None
    for matrix in (IDENTITY, *D4.values()):
        centres = [apply(matrix, (0, 0), centre(c)) for c in cells]
        mx = min(p[0] for p in centres)
        my = min(p[1] for p in centres)
        norm = tuple(sorted((p[0] - mx, p[1] - my) for p in centres))
        if best is None or norm < best:
            best = norm
    assert best is not None
    return best


def orbit_and_validity(cell: Cell, matrix, shift, n: int) -> Tuple[FrozenSet[Cell], bool]:
    """Orbit of a cell under g, and whether the whole orbit stays on the board."""
    start = centre(cell)
    point = start
    cells: List[Cell] = []
    for _ in range(4):
        point = apply(matrix, shift, point)
        cells.append(cell_of(point))
        if point == start:
            break
    orb = frozenset(cells)
    valid = all(0 <= r < n and 0 <= c < n for (r, c) in orb)
    return orb, valid


def _candidate_shifts(n: int) -> Iterator[Tuple[int, int]]:
    """Even translations that can map at least one board cell to a board cell."""
    lo, hi = -2 * n, 2 * n
    for tx in range(lo, hi + 1, 2):
        for ty in range(lo, hi + 1, 2):
            yield (tx, ty)


def _is_connected(cells: FrozenSet[Cell]) -> bool:
    if not cells:
        return False
    start = next(iter(cells))
    seen = {start}
    stack = [start]
    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nb = (r + dr, c + dc)
            if nb in cells and nb not in seen:
                seen.add(nb)
                stack.append(nb)
    return len(seen) == len(cells)


def generate_shapes(n: int, k: int, verbose: bool = True) -> Dict[Tuple, ShapeInfo]:
    """All connected shapes of size <= k that are symmetric under some D4 element.

    Returns a dict keyed by canonical form.
    """
    t_start = time.time()
    shapes: Dict[Tuple, ShapeInfo] = {}

    for name, matrix in D4.items():
        for shift in _candidate_shifts(n):
            # partition the board into orbits under this element
            orbits: List[FrozenSet[Cell]] = []
            placed: Set[Cell] = set()
            admissible: List[FrozenSet[Cell]] = []
            for r in range(n):
                for c in range(n):
                    cell = (r, c)
                    if cell in placed:
                        continue
                    orb, valid = orbit_and_validity(cell, matrix, shift, n)
                    placed |= orb
                    if valid:
                        admissible.append(orb)
            if not admissible:
                continue

            neighbour_cache: Dict[FrozenSet[Cell], Set[int]] = {}

            for seed_index, seed in enumerate(admissible):
                seed_min = min(seed)
                # grow: sets are unions of orbits, each one touching the current
                # set, all with min cell > seed_min so the seed holds the minimum
                start = seed
                counter = 0
                seen: Set[FrozenSet[Cell]] = {start}
                stack: List[FrozenSet[Cell]] = [start]
                while stack:
                    current = stack.pop()
                    if _is_connected(current):
                        key = canonical(current)
                        if key not in shapes:
                            shapes[key] = analyse(current)
                    room = k - len(current)
                    if room <= 0:
                        continue
                    for idx, orb in enumerate(admissible):
                        if idx == seed_index or orb & current:
                            continue
                        if min(orb) < seed_min:
                            continue          # would beat the seed for minimum
                        if len(orb) > room:
                            continue
                        if not any(
                            (r + dr, c + dc) in current
                            for (r, c) in orb
                            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
                        ):
                            continue          # must touch what we already have
                        nxt = current | orb
                        if nxt in seen:
                            continue
                        seen.add(nxt)
                        stack.append(nxt)
                    counter += 1

    if verbose:
        by_size: Dict[int, int] = {}
        for info in shapes.values():
            by_size[info.size] = by_size.get(info.size, 0) + 1
        print(f'shapes (n={n}, K={k}): {len(shapes)} distinct in {time.time()-t_start:.2f}s')
        for size in sorted(by_size):
            print(f'   size {size:2d}: {by_size[size]:6d} shapes')
        with_capitol = sum(1 for i in shapes.values() if i.capitol is not None)
        print(f'   with capitol: {with_capitol}   without: {len(shapes)-with_capitol}')
    return shapes


if __name__ == '__main__':
    import sys
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 5
    k = int(sys.argv[2]) if len(sys.argv) > 2 else 5
    got = generate_shapes(n, k)
    # sanity: the example states must appear
    example = [
        [(0, 0), (1, 0), (2, 0), (3, 1), (3, 2), (3, 3), (2, 1)],
        [(0, 2), (0, 3), (1, 2), (1, 3)],
        [(2, 2), (2, 3), (3, 2)],
    ]
    for cells in example:
        key = canonical(frozenset(cells))
        info = got.get(key)
        print(f'example state size={len(cells)} present={info is not None} '
              f'capitol={info.capitol if info else None}')
